CREATE TABLE IF NOT EXISTS contract_state (id INTEGER PRIMARY KEY CHECK(id=1), version INTEGER NOT NULL, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_log (id INTEGER PRIMARY KEY AUTOINCREMENT, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reports (path TEXT PRIMARY KEY, content TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, payload TEXT NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS session_leases (session_id TEXT PRIMARY KEY, owner TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS quota_budget (id INTEGER PRIMARY KEY CHECK(id=1), used INTEGER NOT NULL DEFAULT 0, session_usage TEXT NOT NULL DEFAULT '{}');
INSERT OR IGNORE INTO quota_budget(id,used,session_usage) VALUES(1,0,'{}');
CREATE TABLE IF NOT EXISTS quota_reservations (id TEXT PRIMARY KEY, session_id TEXT NOT NULL, amount INTEGER NOT NULL, applied INTEGER NOT NULL DEFAULT 0, settled INTEGER NOT NULL DEFAULT 0, actual INTEGER);